#include <iostream>
#include <fstream>
int main() {
    {
        std::ofstream out("demo_bin.bin", std::ios::binary);
        int a[3] = {7, 8, 9};
        out.write(reinterpret_cast<const char*>(a), sizeof(a));
    }
    std::ifstream in("demo_bin.bin", std::ios::binary);
    int b[3];
    in.read(reinterpret_cast<char*>(b), sizeof(b));
    std::cout << b[0] << ' ' << b[1] << ' ' << b[2] << '\n';
}
